CustomField.formula:
if( INCLUDES(Launch_Type__c, "Digital")=false && INCLUDES(Launch_Type__c, "CXP")=false, "" ,
IF(IsBlank( Digital_Go_Live_Date_Manual__c), "Digital Go Live Date"+BR(), "") + IF(TEXT(Budget_Status__c) = "Complete" || TEXT(Budget_Status__c) = "Placeholder", "", "Budget Not in Budget App"+BR()) + IF(TEXT(Account__r.Website_Providers__c) = "" && TEXT(Account__r.TVM_Website_Status__c) = "", "Website Provider"+BR(), "") + IF( PRIMARY_DOMAIN__c = "", "PRIMARY DOMAIN"+BR(), "") + IF(OR( Buy_Sell__c , Offers_Inventory__c), "", "Offers + Inventory"+BR()) + IF(TEXT( In_program_selection__c) = "" , "In Program Selection"+BR(), "") + IF(ISBLANK(CallRevu_Number_Sales__c), "CallRevu Number Sales"+BR(), "") + IF(ISBLANK(CallRevu_Number_Service__c), "CallRevu Number Service"+BR(), "") + IF(TEXT(Billing_Section__c) = "", "Billing Selection"+BR(), "") +if(Text(Google_Ads_Account__c)="", "Missing Digital Account Type"+BR(), "")
)
